// src/RegistrationForm.tsx

import React from 'react';
import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { Formik,Form,ErrorMessage,Field } from 'formik';
import * as Yup from 'yup'


interface UserData {
  name: string;
  email: string;
  password: string;
}
const validationSchema = Yup.object().shape({
    name: Yup.string()
      .required('First name is required')
      .min(2, 'Must be 2 characters long'),
    email: Yup.string()
      .required('Email is required')
      .email('Invalid email format'),

    password: Yup.string()
      .required('Password is required')
      .min(6, 'Minimum 6 characters'),
  });

const registerUser = async (newUser: UserData):Promise<UserData> => {
  const response = await axios.post<UserData>('/api/register', newUser);
  return response.data;
};

const RegistrationForm: React.FC = () => {
    const initialValues: UserData = {
        name: '',
        email: '',
        password: '',
      };

  const mutation=useMutation<UserData,Error,UserData>(
    {
        mutationFn:registerUser,
        onSuccess:(data:UserData)=>{
            console.log('user registered',data)
        },
        onError:(error:Error)=>{
            console.error('registration failed',error)
        }
    }
);
const handleSubmit=async(values:UserData)=>{
    mutation.mutate(values);
}


  return (
    <div className="container mt-5 bg-info">
      <h1>SIGN UP PAGE</h1>
      <Formik
        initialValues={initialValues}
        validationSchema={validationSchema}
        onSubmit={handleSubmit}
      >
        {() => (
          <Form>
            <div className="form-group">
              <label htmlFor="name">Name</label>
              <Field className="form-control" name="name" type="text" />
              <ErrorMessage name="name" component="div" className="text-danger" />
            </div>

            <div className="form-group">
              <label htmlFor="email">Email</label>
              <Field className="form-control" name="email" type="text" />
              <ErrorMessage name="email" component="div" className="text-danger" />
            </div>

            <div className="form-group">
              <label htmlFor="password">Password</label>
              <Field className="form-control" name="password" type="password" />
              <ErrorMessage name="password" component="div" className="text-danger" />
            </div>


            <button type="submit" className="btn btn-primary btn-block">Submit</button>

          </Form>
        )}
      </Formik>
    </div> 

  );
};

export default RegistrationForm;
